package com.toir.migration;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import java.sql.*;import java.util.UUID;
import static org.assertj.core.api.Assertions.*;
class RepairCampaignPlanningMigrationPostgresTest {
 @Test void postgres17FullChainEnforcesV4PlanningContracts() throws Exception {Assumptions.assumeTrue(Boolean.parseBoolean(System.getenv("TOIR_LOCAL_PG17")));String db="task4_"+UUID.randomUUID().toString().replace("-","");String admin=env("TOIR_LOCAL_PG_URL","jdbc:postgresql://localhost:5432/postgres"),url=dbUrl(admin,db);try(Connection c=conn(admin);Statement s=c.createStatement()){s.execute("CREATE DATABASE "+db);}try{assertThat(Flyway.configure().dataSource(url,user(),pass()).locations("classpath:db/migration").baselineOnMigrate(true).baselineVersion("0").load().migrate().success).isTrue();try(Connection c=conn(url);Statement s=c.createStatement()){UUID dep=UUID.randomUUID(),type=UUID.randomUUID(),eq=UUID.randomUUID(),campaign=UUID.randomUUID(),a=UUID.randomUUID(),b=UUID.randomUUID();s.execute("INSERT INTO departments(id,code,name,type,is_deleted,created_at,updated_at) VALUES ('"+dep+"','D4','D4','WORKSHOP',false,now(),now())");s.execute("INSERT INTO equipment_types(id,code,name,category,is_deleted,created_at,updated_at) VALUES ('"+type+"','T4','T4','PRODUCTION_EQUIPMENT',false,now(),now())");s.execute("INSERT INTO equipment(id,equipment_type_id,code,name,inventory_number,category,status,is_deleted,created_at,updated_at) VALUES ('"+eq+"','"+type+"','E4','E4','I4','PRODUCTION_EQUIPMENT','ACTIVE',false,now(),now())");s.execute("INSERT INTO repair_campaigns(id,code,name,status,start_date,end_date,total_budget,total_actual,currency_code,scope_type,department_id,version,closure_version,is_deleted,created_at,updated_at) VALUES ('"+campaign+"','RC4','RC4','DRAFT',current_date,current_date,0,0,'UZS','CUSTOM','"+dep+"',0,0,false,now(),now())");item(s,a,campaign,eq,0,"CRITICAL");item(s,b,campaign,eq,1,"MEDIUM");UUID edge=UUID.randomUUID();edge(s,edge,campaign,a,b);constraint(()->edge(s,UUID.randomUUID(),campaign,a,b),"uq_repair_campaign_dependencies_active_edge");constraint(()->edge(s,UUID.randomUUID(),campaign,a,a),"chk_repair_campaign_dependency_not_self");constraint(()->edge(s,UUID.randomUUID(),campaign,UUID.randomUUID(),b),"fk_repair_campaign_dependency_predecessor");constraint(()->assignment(s,UUID.randomUUID(),campaign,a,null,null,null,"A","now()","now()+interval '1 hour'"),"chk_repair_campaign_resource_exactly_one");constraint(()->assignment(s,UUID.randomUUID(),campaign,a,UUID.randomUUID(),null,null,"A","now()","now()"),"chk_repair_campaign_resource_window");try(ResultSet r=s.executeQuery("UPDATE repair_campaigns SET version=version+1 WHERE id='"+campaign+"' RETURNING version")){assertThat(r.next()).isTrue();assertThat(r.getLong(1)).isEqualTo(1L);}}}finally{try(Connection c=conn(admin);Statement s=c.createStatement()){s.execute("DROP DATABASE IF EXISTS "+db+" WITH (FORCE)");}}}
 static void item(Statement s,UUID id,UUID c,UUID e,int order,String p)throws Exception{s.execute("INSERT INTO repair_campaign_work_items(id,repair_campaign_id,source_type,equipment_id,title,status,order_number,priority,is_deleted,created_at,updated_at) VALUES ('"+id+"','"+c+"','MANUAL','"+e+"','item','PENDING',"+order+",'"+p+"',false,now(),now())");}
 static void edge(Statement s,UUID id,UUID c,UUID p,UUID x)throws Exception{s.execute("INSERT INTO repair_campaign_work_dependencies(id,repair_campaign_id,predecessor_work_item_id,successor_work_item_id,is_deleted,created_at,updated_at) VALUES ('"+id+"','"+c+"','"+p+"','"+x+"',false,now(),now())");}
 static void assignment(Statement s,UUID id,UUID c,UUID w,UUID e,UUID b,UUID x,String shift,String start,String end)throws Exception{s.execute("INSERT INTO repair_campaign_resource_assignments(id,repair_campaign_id,work_item_id,employee_id,brigade_id,counteragent_id,shift_code,planned_start_at,planned_end_at,is_deleted,created_at,updated_at) VALUES ('"+id+"','"+c+"','"+w+"',"+q(e)+","+q(b)+","+q(x)+",'"+shift+"',"+start+","+end+",false,now(),now())");}
 static String q(UUID x){return x==null?"NULL":"'"+x+"'";}static void constraint(Call c,String n){assertThatThrownBy(c::run).hasMessageContaining(n);}interface Call{void run()throws Exception;}static Connection conn(String u)throws Exception{return DriverManager.getConnection(u,user(),pass());}static String dbUrl(String u,String d){int q=u.indexOf('?');String x=q<0?"":u.substring(q),b=q<0?u:u.substring(0,q);return b.substring(0,b.lastIndexOf('/')+1)+d+x;}static String user(){return env("TOIR_LOCAL_PG_USER","postgres");}static String pass(){return env("TOIR_LOCAL_PG_PASSWORD","");}static String env(String n,String d){String v=System.getenv(n);return v==null?d:v;}
}
